#else
  pref("devtools.aboutdebugging.showHiddenAddons", true);
#endif

// Add some extra logging to the console, for debugging
pref("devtools.aboutdebugging.showReduxActionsInConsole", false);

// Map top-level await expressions in the console
pref("devtools.debugger.features.map-await-expression", true);

// This relies on javascript.options.asyncstack as well or it has no effect.
pref("devtools.debugger.features.async-captured-stacks", true);
pref("devtools.debugger.features.async-live-stacks", false);

// This supports showing stylesheet sources in the debugger
pref("devtools.debugger.features.stylesheets-in-debugger", false);

// When debugging a website, this pref controls if extension content scripts applied
// to the currently debugged page should be shown in the Debugger Source Tree
// As of bug 1936360, Firefox defaults to false, but we default to `true` to
// ease extension debugging.
pref("devtools.debugger.show-content-scripts", true);

pref("devtools.debugger.hide-ignored-sources", false);
#if defined(NIGHTLY_BUILD)
  pref("devtools.debugger.features.codemirror-next", true);
#else
  pref("devtools.debugger.features.codemirror-next", false);
#endif

// Disable autohide for DevTools popups and tooltips.
// This is currently not exposed by any UI to avoid making
// about:devtools-toolbox tabs unusable by mistake.
pref("devtools.popup.disable_autohide", false);

// Add support for high contrast mode
#if defined(NIGHTLY_BUILD)
  pref("devtools.high-contrast-mode-support", true);
#else
  pref("devtools.high-contrast-mode-support", false);
#endif

// Telemetry settings.

// Server to submit telemetry pings to.
pref("toolkit.telemetry.server", "https://incoming-telemetry.thunderbird.net");
pref("toolkit.telemetry.server_owner", "Thunderbird");

// Determines if Telemetry pings can be archived locally.
pref("toolkit.telemetry.archive.enabled", true);
// Enables sending the shutdown ping when Thunderbird shuts down.
pref("toolkit.telemetry.shutdownPingSender.enabled", true);
// Enables sending the shutdown ping using the pingsender from the first session.
pref("toolkit.telemetry.shutdownPingSender.enabledFirstSession", false);
// Enables sending a duplicate of the first shutdown ping from the first session.
pref("toolkit.telemetry.firstShutdownPing.enabled", true);
// Enables sending the 'new-profile' ping on new profiles.
pref("toolkit.telemetry.newProfilePing.enabled", true);
// Enables sending 'update' pings on Thunderbird updates.
pref("toolkit.telemetry.updatePing.enabled", true);
// Enables sending 'bhr' pings when the app hangs.
pref("toolkit.telemetry.bhrPing.enabled", true);
